Lemma node_ok_of_pnode_sysno : forall ms model x8 n I evs nx,
  ms_svc_pending ms = Some x8 ->
  bv_unsigned x8 = n ->
  injected_arm n = None ->
  pnode_ok (mkCfg ms model) I evs nx ->
